import re, base64, zlib, os

def extract_pdf_text(filepath):
    with open(filepath, 'rb') as f:
        raw = f.read()
    text = ''
    # Find all stream objects
    for m in re.finditer(rb'stream\r?\n(.*?)\r?\nendstream', raw, re.DOTALL):
        data = m.group(1)
        # Check if ASCII85 encoded
        if b'/ASCII85Decode' in raw and b'~>' in data:
            # Remove trailing ~>
            idx = data.find(b'~>')
            if idx != -1:
                data = data[:idx+2]
            try:
                # a85decode with adobe=False
                decoded = base64.a85decode(data, adobe=False)
            except:
                try:
                    decoded = base64.a85decode(data.rstrip(), adobe=False)
                except:
                    continue
        elif b'/FlateDecode' in raw and b'/ASCII85Decode' not in raw:
            decoded = data
        else:
            decoded = data
        # Now try to inflate
        try:
            inflated = zlib.decompress(decoded)
            text += inflated.decode('latin-1')
        except:
            # Try with raw deflate
            try:
                inflated = zlib.decompress(decoded, -15)
                text += inflated.decode('latin-1')
            except:
                pass
    return text

# Extract text from all PDFs
doc_dir = '/app/documents'
for fname in sorted(os.listdir(doc_dir)):
    if fname.endswith('.pdf'):
        fpath = os.path.join(doc_dir, fname)
        content = extract_pdf_text(fpath)
        print(f"\n{'='*60}")
        print(f"FILE: {fname}")
        print(f"{'='*60}")
        print(content)
